head.script:
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 gridView header부분의 'name3'항목에는 정렬아이콘(상,하 화살표)표시여부를 확인한다.
    //1. After executing the sample, check whether the sort icon (up and down arrow) is displayed in the 'name3' item of the gridView header part.
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. 'name3'항목에는 정렬아이콘(상,하 화살표)이 표시되지 않는다. 정상(이전에는 표시되어 보여짐)
    //1. The sort icon (up and down arrows) is not displayed in the 'name3' item. Normal (previously shown)
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_column1').children().hasClass('w2grid_head_sort_div_main') == false", "true");
    //5.0_4.4420B.20210527.095308_1.5 이후변경
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_column1').children().hasClass('w2grid_head_sort_none') == false", "true");
    //Test step 2. 'name1'항목을 더블클릭하여 sorting되는지 확인한다.
    //2. Double-click on the 'name1' item to see if it is sorting.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'wq_uuid_3_column5')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'wq_uuid_3_column5')");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. 'name1'항목이 정상적으로 sorting되어진다.
    //2. The 'name1' item is normally sorted.
    WebSquare.wUnit.addCommand("assert", "parseInt(WebSquare.wUnit.getObjById('wq_uuid_3_cell_0_0').innerText) > parseInt(WebSquare.wUnit.getObjById('wq_uuid_3_cell_1_0.innerText'))", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //showSortableImage = "true"
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 15-Jun-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
